const fmt = (n) => Number(n || 0).toLocaleString('de-DE');
const onOff = (v) => (v ? '✅' : '❌');
const bar = (have, need, w = 14) => {
  const p = need > 0 ? Math.min(1, have / need) : 0;
  const f = Math.round(p * w);
  return '█'.repeat(f) + '░'.repeat(w - f);
};

