/* 💜 Globale HelloKitty Baby Maxi 💔-Signatur — wird an JEDE ausgehende Text-/Caption- */
/* Nachricht angehängt (siehe withGlobalSignature() weiter unten).     */
const LOVEBOT_SIGNATURE_LINE1 = '🌧️ maxichen.de · niemand da';
const LOVEBOT_SIGNATURE_LINE2 = '> 🥀 hellokitty baby maxi by maxichen 2026 · niemand schreibt zurück 💔';
const LOVEBOT_SIGNATURE_LINE3 = '> 💗 signiert: by maxichen · kopieren verboten · es tut weh';
const LOVEBOT_SIGNATURE = `${LOVEBOT_SIGNATURE_LINE1}\n${LOVEBOT_SIGNATURE_LINE2}\n${LOVEBOT_SIGNATURE_LINE3}`;

/* Hängt die Signatur an `text`/`caption` an — aber nur einmal (keine */
/* Doppelung, falls eine Nachricht schon manuell die Signatur trägt). */
function withGlobalSignature(content) {
  if (!content || typeof content !== 'object' || Array.isArray(content)) return content;
  const out = { ...content };
  for (const field of ['text', 'caption']) {
    const val = out[field];
    if (typeof val === 'string' && val.length && !val.includes('maxichen.de')) {
      out[field] = `${val}\n\n${LOVEBOT_SIGNATURE}`;
    }
  }
  return out;
}

/* Gleiches Prinzip für die "rohen" Rich-Response-JSON-Payloads       */
/* (sock.sendJson — Meta-AI-Karten, Ban-Checker, etc.). Hängt die     */
/* Signatur an den letzten sichtbaren "messageText"-Textblock an,     */
/* damit Nutzer sie auch in Karten/Rich-Responses sehen.              */
function withGlobalSignatureRich(json) {
  try {
    if (!json || typeof json !== 'object') return json;
    const subs = json?.botForwardedMessage?.message?.richResponseMessage?.submessages;
    if (Array.isArray(subs) && subs.length) {
      for (let i = subs.length - 1; i >= 0; i--) {
        const s = subs[i];
        if (s && typeof s.messageText === 'string' && s.messageText.length) {
          if (!s.messageText.includes('maxichen.de')) {
            s.messageText = `${s.messageText}\n\n${LOVEBOT_SIGNATURE}`;
          }
          const kiLabel = kiLabelText((readDb && readDb() && readDb().meta) || {});
          if (kiLabel && !s.messageText.includes(kiLabel)) {
            s.messageText = `${s.messageText}\n\n${kiLabel}`;
          }
          break;
        }
      }
    }
  } catch (e) {}
  return json;
}

/* 🤖 Offizielles Meta-KI-Label — wird als contextInfo-Feld an JEDE
   ausgehende Text-/Caption-Nachricht angehängt (zentral über baileys
   sock.sendMessage, niemals an Reaktionen/Löschen/Weiterleitungen). */
const KI_LABEL_DEFAULT = '🤖 KI-Antwort von HelloKitty Baby Maxi 💔';

function kiLabelText(meta = {}) {
  if (!meta || typeof meta !== 'object') return KI_LABEL_DEFAULT;
  const raw = meta.kiLabel || meta.kiText || meta.ki || KI_LABEL_DEFAULT;
  const s = String(raw || '').trim();
  return s || KI_LABEL_DEFAULT;
}

function withMetaAILabel(content, meta = {}) {
  if (!content || typeof content !== 'object' || Array.isArray(content)) return content;
  const out = { ...content };
  const label = kiLabelText(meta);
  if (!out.contextInfo) out.contextInfo = {};
  /* Offizielles Meta-KI-Label über contextInfo markieren. */
  out.contextInfo.aiGenerated = true;
  out.contextInfo.aiLabel = label;
  /* Zusätzlich ein kurzer, sichtbarer Hinweis am Textende (falls WhatsApp
     das Protokoll-Feld nicht anzeigt), ohne Doppelung. */
  for (const field of ['text', 'caption']) {
    const val = out[field];
    if (typeof val === 'string' && val.length && !val.includes(label)) {
      out[field] = `${val}\n\n${label}`;
    }
  }
  return out;
}
const sessionDevPulseSent = new Set();

function extractInviteCodeFromLink(link) {
  if (!link || typeof link !== 'string') {
    return '';
  }

  const trimmed = link.trim();
  if (!trimmed) {
    return '';
  }

  try {
    const parsed = new URL(trimmed);
    const path = parsed.pathname.replace(/^\/+/u, '').replace(/\/+/gu, '/');
    const segment = path.split('/').filter(Boolean)[0] || '';
    if (segment) {
      return segment;
    }
  } catch (error) {
    // ignore invalid URL parsing and fall through to the plain string fallback
  }

  return trimmed.split(/[/?#]/u).filter(Boolean)[0] || '';
}

/* ═══  AO — Beitrittsanfragen automatisch genehmigen ═══
   Config lebt in der globalen DB (db.aoAutoApprove: { all, groups }) —
   keine neue Datei, kein neuer Ballast. Der Loop prüft alle 60 s. */
const aoLoopStarted = new Set();
function aoReadCfg() {
  try {
    const db = readDb();
    if (!db.aoAutoApprove || typeof db.aoAutoApprove !== 'object') db.aoAutoApprove = { all: false, groups: {} };
    if (!db.aoAutoApprove.groups || typeof db.aoAutoApprove.groups !== 'object') db.aoAutoApprove.groups = {};
    return db;
  } catch (aoCfgErr) {
    return { aoAutoApprove: { all: false, groups: {} } };
  }
}
async function aoApprovePending(sock, targets) {
  const lines = [];
  let approved = 0;
  for (const gid of targets) {
    try {
      const reqs = await sock.groupRequestParticipantsList(gid);
      const jids = (reqs || []).map((r) => r && r.jid).filter(Boolean);
      if (jids.length) {
        await sock.groupRequestParticipantsUpdate(gid, jids, 'approve');
        approved += jids.length;
        lines.push('✅ ' + jids.length + ' Anfrage(n) genehmigt in ' + cleanId(gid));
      }
    } catch (aoPendErr) {
      lines.push('⚠️ Anfragen in ' + cleanId(gid) + ': ' + (aoPendErr?.message || aoPendErr));
    }
    await delay(800);
  }
  return { approved, lines };
}
function startAoAutoApproveLoop(sock) {
  const sid = String(SESSION_ID || 'main');
  if (aoLoopStarted.has(sid)) return;
  aoLoopStarted.add(sid);
  setInterval(async () => {
    try {
      const cfg = aoReadCfg().aoAutoApprove;
      if (!cfg.all && Object.keys(cfg.groups || {}).length === 0) return;
      const targets = cfg.all
        ? Object.keys(await sock.groupFetchAllParticipating())
        : Object.keys(cfg.groups || {});
      const res = await aoApprovePending(sock, targets);
      if (res.approved > 0) {
        console.log(c.bold + c.brightGreen + '✅ [ao] ' + res.approved + ' Beitrittsanfrage(n) automatisch genehmigt' + c.reset);
      }
    } catch (aoLoopErr) { /* ao bleibt still, wenn es nicht darf */ }
  }, 60000);
}

