    if (silentGroupJoins.has(gid)) return false;

    const key = SESSION_ID + '|' + gid;
    const now = Date.now();
    const last = recentJoinIntros.get(key) || 0;
    if (now - last < JOIN_INTRO_MIN_MS) return false;
    recentJoinIntros.set(key, now);

