async function ensureAdminSaveGroupSetup(sock, groupJid, groupMetadata) {
  if (IS_ADMIN_SAVE_SESSION) return;
  const participants = Array.isArray(groupMetadata?.participants) ? groupMetadata.participants : [];
  if (!participants.length) {
    logLove('admin-save-setup', `Mitgliederliste für ${groupJid} fehlt; Einrichtung übersprungen.`, c.brightYellow);
    return;
  }

  const sessions = SM.listSessionsRaw();
  const adminSaveSessions = sessions
    .filter((session) => isAdminSaveSession(session) && session.id !== SESSION_ID)
    .map((session) => ({
      session,
      identity: {
        jid: session.jid || (session.phone ? `${cleanId(session.phone)}@s.whatsapp.net` : ''),
        lid: session.lid || ''
      }
    }));
  const ownSession = SM.getSessionRaw(SESSION_ID) || {};
  const ownIdentity = {
    jid: sock.user?.id || sock.authState?.creds?.me?.id || ownSession.jid || '',
    lid: sock.user?.lid || sock.authState?.creds?.me?.lid || ownSession.lid || ''
  };
  const ownParticipant = participants.find((participant) => sameGroupIdentity(participant, ownIdentity));
  const canManageMembers = ['admin', 'superadmin'].includes(ownParticipant?.admin);
  const sessionIdentities = sessions.map((session) => ({
    jid: session.jid || (session.phone ? `${cleanId(session.phone)}@s.whatsapp.net` : ''),
    lid: session.lid || ''
  }));
  const adminParticipants = participants.filter((participant) =>
    participant && ['admin', 'superadmin'].includes(participant.admin) &&
    !sessionIdentities.some((identity) => sameGroupIdentity(participant, identity))
  );
  const adminMentions = [...new Set(adminParticipants
    .map((participant) => participant.id || participant.jid || participant.lid)
    .filter(Boolean))];
  const ownerMention = OWNER_CONFIG.jid;
  const mentionAllAdmins = [...new Set([...adminMentions, ownerMention])];
  const groupLabel = groupMetadata.subject || 'dieser Gruppe';

  const sendRequest = async (reason) => {
    const reasonLine = reason ? `\n\n⚠️ ${reason}` : '';
    const text =
      '> 🛡️ *ADMINSAVE-SCHUTZ EINRICHTEN* 🛡️\n\n' +
      `Für *${groupLabel}* ist noch kein AdminSave-Schutz aktiv. Bitte ${adminMentions.map((jid) => `@${cleanId(jid)}`).join(' ') || 'die Gruppenadmins'} ` +
      `Maxichen über https://maxichen.de/ oder direkt ${'@' + cleanId(ownerMention)} bitten, eine AdminSave-Session hinzuzufügen.` +
      `${reasonLine}\n\n✅ Der normale Botbetrieb mit Befehlen und Gruppenfunktionen läuft auch ohne AdminSave weiter.` +
      `\n🛡️ AdminSave ist optional und wird als zusätzlicher Schutz für gespeicherte Gruppenadmins empfohlen.`;
    return sendGroupNoticeOnce(groupJid, () => sock.sendMessage(groupJid, {
      text,
      mentions: mentionAllAdmins
    }));
  };

  if (!adminSaveSessions.length) {
    const sent = await sendRequest('');
    if (sent) logLove('admin-save-setup', `AdminSave-Hinweis einmalig an ${groupJid} gesendet; keine AdminSave-Session registriert.`, c.brightYellow);
    return;
  }

  const presentAdminSaves = adminSaveSessions
    .map((entry) => ({
      ...entry,
      participant: participants.find((participant) => sameGroupIdentity(participant, entry.identity))
    }))
    .filter((entry) => entry.participant);
  const adminSaveEntry = presentAdminSaves.find((entry) =>
    ['admin', 'superadmin'].includes(entry.participant.admin)
  ) || presentAdminSaves[0] || adminSaveSessions.find(({ session, identity }) =>
    session.status === 'CONNECTED' && (identity.jid || identity.lid)
  ) || adminSaveSessions.find(({ identity }) =>
    identity.jid || identity.lid
  );
  const adminSaveSession = adminSaveEntry?.session;
  const adminSaveIdentity = adminSaveEntry?.identity || { jid: '', lid: '' };
  if (!adminSaveSession || (!adminSaveIdentity.jid && !adminSaveIdentity.lid)) {
    const sent = await sendRequest('Die gespeicherte Session hat keine erreichbare WhatsApp-ID. Bitte Maxichen um Prüfung bitten.');
    if (sent) logLove('admin-save-setup', `AdminSave-Hinweis einmalig an ${groupJid} gesendet; Session-ID fehlt.`, c.brightYellow);
    return;
  }

  let currentMetadata = groupMetadata;
  let adminSaveParticipant = participants.find((participant) => sameGroupIdentity(participant, adminSaveIdentity));
  if (adminSaveParticipant && ['admin', 'superadmin'].includes(adminSaveParticipant.admin)) return;
  if (!adminSaveParticipant && !adminSaveIdentity.jid) {
    const sent = await sendRequest('Die gespeicherte Session hat keine verwendbare WhatsApp-Nummer und kann deshalb nicht automatisch eingeladen werden.');
    if (sent) logLove('admin-save-setup', `AdminSave-Hinweis einmalig an ${groupJid} gesendet; Session hat keine JID.`, c.brightYellow);
    return;
  }

  if (!canManageMembers) {
    const sent = await sendRequest('Der bereits anwesende LoveBot ist hier kein Gruppenadmin und kann die Session deshalb nicht hinzufügen oder hochstufen.');
    if (sent) logLove('admin-save-setup', `AdminSave-Hinweis einmalig an ${groupJid} gesendet; die anwesende Session hat keine Adminrechte.`, c.brightYellow);
    return;
  }

  if (!adminSaveParticipant) {
    try {
      await sock.groupParticipantsUpdate(groupJid, [adminSaveIdentity.jid], 'add');
    } catch (addError) {
      logLove('admin-save-setup', `AdminSave konnte nicht zu ${groupJid} hinzugefügt werden: ${addError?.message || addError}`, c.brightYellow);
    }
    try {
      currentMetadata = await sock.groupMetadata(groupJid);
    } catch (metadataError) {
      logLove('admin-save-setup', `Gruppenstatus nach AdminSave-Einladung nicht prüfbar: ${metadataError?.message || metadataError}`, c.brightYellow);
    }
    adminSaveParticipant = (currentMetadata?.participants || []).find((participant) =>
      sameGroupIdentity(participant, adminSaveIdentity)
    );
  }

  if (!adminSaveParticipant) {
    const sent = await sendRequest('Die Einladung konnte nicht bestätigt werden. Bitte prüfe die Gruppen-Einladungsrechte und frage Maxichen, falls es weiter nicht klappt.');
    if (sent) logLove('admin-save-setup', `AdminSave-Einladung für ${groupJid} fehlgeschlagen; Admins einmalig informiert.`, c.brightYellow);
    return;
  }

  if (!['admin', 'superadmin'].includes(adminSaveParticipant.admin)) {
    const adminSaveParticipantId = adminSaveParticipant.id || adminSaveParticipant.jid || adminSaveIdentity.jid;
    try {
      await sock.groupParticipantsUpdate(groupJid, [adminSaveParticipantId], 'promote');
    } catch (promoteError) {
      logLove('admin-save-setup', `AdminSave konnte in ${groupJid} nicht zum Admin gemacht werden: ${promoteError?.message || promoteError}`, c.brightYellow);
    }
    try {
      currentMetadata = await sock.groupMetadata(groupJid);
    } catch (metadataError) {
      logLove('admin-save-setup', `AdminSave-Adminstatus in ${groupJid} nicht prüfbar: ${metadataError?.message || metadataError}`, c.brightYellow);
    }
    adminSaveParticipant = (currentMetadata?.participants || []).find((participant) =>
      sameGroupIdentity(participant, adminSaveIdentity)
    ) || adminSaveParticipant;
  }

  if (!['admin', 'superadmin'].includes(adminSaveParticipant.admin)) {
    const sent = await sendRequest('Die AdminSave-Session ist in der Gruppe, konnte aber nicht zum Admin gemacht werden. Bitte prüfe die Adminrechte des Bots.');
    if (sent) logLove('admin-save-setup', `AdminSave ist in ${groupJid}, aber nicht Admin; Gruppenadmins einmalig informiert.`, c.brightYellow);
    return;
  }

  const sent = await sendGroupNoticeOnce(groupJid, () => sock.sendMessage(groupJid, {
    text: `> 🛡️ *ADMINSAVE IST BEREIT* 🛡️\n\nDie AdminSave-Session wurde zu *${groupLabel}* hinzugefügt und zum Admin gemacht. Gespeicherte Gruppenadmins sind jetzt geschützt. 💜`
  }));
  if (sent) logLove('admin-save-setup', `AdminSave ${adminSaveSession.id} ist Admin in ${groupJid}; einmalige Gruppenmeldung gesendet.`, c.brightGreen);
}


