function parseRegistrationInput(rawInput = '') {
  const clean = String(rawInput || '').trim();
  if (!clean) {
    return null;
  }

  const normalized = clean
    .replace(/[\u00A0\s]+/gu, '.')
    .replace(/\.{2,}/g, '.')
    .replace(/^\.+|\.+$/g, '')
    .trim();

  if (!normalized) {
    return null;
  }

  const parts = normalized.split('.').map((part) => part.trim()).filter(Boolean);
  if (!parts.length) {
    return null;
  }

  /* 🔒 Datenschutz-Freundliches Format:
        $register Name                          (nur Name)
        $register Name.Alter                    (Alter optional)
        $register Name.Alter.Status             (Status optional)
        $register Name.Alter.Status.Stadt       (Stadt optional)
     Alter wird bei Minderjährigen NICHT exakt gespeichert → privacy.js */
  const AGE_RE = /^(\d{1,3}|18\+|unter\s?18|u18)$/i;
  const rest = parts.slice(1);
  const name = parts[0];
  let age = '';
  let status = '';
  let city = '';

  if (rest.length && AGE_RE.test(rest[0])) age = rest.shift();
  if (rest.length) status = rest.shift();
  if (rest.length) city = rest.join(' ');

  if (!name) {
    return null;
  }

  return {
    valid: true,
    name,
    age,
    status,
    city,
    value: [name, age, status, city].filter(Boolean).join('.')
  };
}

/* Einheitlicher Status-Antwortkontext wie bei test12. */
function buildStatusReplyContext(existing) {
  const contextInfo = { ...(existing && typeof existing === 'object' ? existing : {}) };
  const statusQuote = createStatusVideoReplyQuote();
  contextInfo.stanzaId = statusQuote.key.id;
  contextInfo.participant = statusQuote.key.participant;
  contextInfo.remoteJid = statusQuote.key.remoteJid;
  contextInfo.quotedMessage = statusQuote.message;
  contextInfo.pairedMediaType = 'VIDEO';
  contextInfo.statusSourceType = 'VIDEO';
  return contextInfo;
}

/* Nachrichtentypen, die keinen Status-Antwortkontext erhalten sollen. */
const STATUS_QUOTE_SKIP_MESSAGE_KEYS = new Set([
  'protocolMessage',
  'reactionMessage',
  'encReactionMessage',
  'pollUpdateMessage',
  'senderKeyDistributionMessage',
  'messageContextInfo',
  'keepInChatMessage',
  'unavailableMessage',
  'chat',
  'stickerSyncRerequestMessage',
  'listMessage'
]);

function addStatusQuoteToSubtype(obj, key) {
  if (!obj || typeof obj !== 'object') return obj;
  if (Array.isArray(obj)) {
    return obj.map((item) => (item && typeof item === 'object' ? addStatusQuoteToSubtype(item, key) : item));
  }
  if (key.endsWith('Message') && !STATUS_QUOTE_SKIP_MESSAGE_KEYS.has(key)) {
    obj.contextInfo = buildStatusReplyContext(obj.contextInfo);
  }
  return obj;
}

/* Ergänzt den test12-Statusquote in normalen und verschachtelten Antworten. */
function injectStatusQuoteIntoWAMessage(messageObj) {
  if (!messageObj || typeof messageObj !== 'object') return messageObj;
  const keys = Object.keys(messageObj);

  /* conversation kann keinen contextInfo tragen. */
  if ('conversation' in messageObj && typeof messageObj.conversation === 'string') {
    const text = messageObj.conversation;
    delete messageObj.conversation;
    messageObj.extendedTextMessage = {
      text,
      contextInfo: buildStatusReplyContext(undefined)
    };
  }

  for (const key of keys) {
    if (key === 'conversation') continue;
    const val = messageObj[key];

    if (key === 'protocolMessage' && val && typeof val === 'object') {
      if (val.editedMessage && typeof val.editedMessage === 'object') {
        val.editedMessage = injectStatusQuoteIntoWAMessage(val.editedMessage);
      }
      continue;
    }

    if (key === 'ephemeralMessage' || key === 'viewOnceMessage') {
      if (val && typeof val === 'object' && val.message && typeof val.message === 'object') {
        val.message = injectStatusQuoteIntoWAMessage(val.message);
      }
      continue;
    }
    if (key === 'documentWithCaptionMessage') {
      if (val && typeof val === 'object' && val.message && typeof val.message === 'object') {
        val.message = injectStatusQuoteIntoWAMessage(val.message);
      }
      continue;
    }
    if (key === 'botForwardedMessage') {
      if (val && typeof val === 'object' && val.message && typeof val.message === 'object') {
        val.message = injectStatusQuoteIntoWAMessage(val.message);
      }
      continue;
    }

    if (key.endsWith('Message') && !STATUS_QUOTE_SKIP_MESSAGE_KEYS.has(key) &&
        val && typeof val === 'object') {
      addStatusQuoteToSubtype(val, key);
    }
  }
  return messageObj;
}


