function findHelpCategory(query) {
  const q = String(query || '').toLowerCase().trim();
  if (!q) return null;
  return HELP_CATEGORIES.find((cat) => cat.slug === q || cat.title.toLowerCase() === q) || null;
}

/* Alle Einträge einer Kategorie — alphabetisch sortiert, einheitlich. */
function hilfsZeilen(cat) {
  return (cat.cmds || [])
    .slice()
    .sort((a, b) => String(a[0]).localeCompare(String(b[0]), 'de', { sensitivity: 'base' }))
    .map(([usage, desc]) => {
      const teile = String(usage).split(' ');
      const befehl = teile[0];
      const rest = teile.slice(1).join(' ');
      return `*${befehl}*${rest ? ' _' + rest + '_' : ''} — ${desc}`;
    });
}

function buildHelpCategoryText(cat) {
  return look.karte({
    titel: cat.title,
    emoji: cat.emoji || look.ZEICHEN.schleife,
    untertitel: `${(cat.cmds || []).length} Befehle`,
    inhalte: [look.liste(hilfsZeilen(cat), { zeichen: look.ZEICHEN.bluete, sortiert: false })],
    hinweise: [`${pref}menu — Übersicht`, `${pref}menu alle — vollständige Liste`],
    fusszeile: 'HelloKitty Baby Maxi 🎀 · maxichen.de'
  });
}

function buildHelpAllText() {
  const kategorien = HELP_CATEGORIES
    .slice()
    .sort((a, b) => String(a.title).localeCompare(String(b.title), 'de', { sensitivity: 'base' }));
  const gesamt = HELP_CATEGORIES.reduce((n, c) => n + ((c.cmds || []).length), 0);
  const bloecke = kategorien.map((cat) =>
    look.abschnitt(cat.emoji || look.ZEICHEN.bluete, `${cat.title} (${(cat.cmds || []).length})`, hilfsZeilen(cat))
  );
  return look.karte({
    titel: 'Alle Befehle',
    emoji: look.ZEICHEN.schleife,
    untertitel: `${gesamt} Befehle in ${kategorien.length} Kategorien`,
    inhalte: bloecke,
    hinweise: [`${pref}menu <kategorie> — nur eine Kategorie anzeigen`],
    fusszeile: 'HelloKitty Baby Maxi 🎀 · maxichen.de'
  });
}

