/* Liest den HTTP-/Server-Statuscode aus einem Boom-Fehler.           */
/* assertNodeErrorFree() in Baileys steckt den Code in err.data,      */
/* Socket-Fehler nutzen err.output.statusCode.                        */
function extractStatusCode(err) {
  if (!err || typeof err !== 'object') {
    return null;
  }
  if (typeof err.data === 'number' && Number.isFinite(err.data)) {
    return err.data;
  }
  if (err.output && typeof err.output.statusCode === 'number' && Number.isFinite(err.output.statusCode)) {
    return err.output.statusCode;
  }
  return null;
}

/* Wertet das rohe usync-IQ aus, OHNE den Baileys-Parser zu nutzen.   */
/* Der Baileys-Parser (USyncQuery.parseUSyncQueryResult) wirft bei    */
/* einem <error>-Knoten weg und verschluckt damit genau den Code, der */
/* für die Ban-Erkennung gebraucht wird.                              */
function collectUsyncSignals(rawResult) {
  const out = {
    exists: null,
    deviceCount: null,
    hasStatus: null,
    userJid: '',
    errorCodes: []
  };

  if (!rawResult || typeof rawResult !== 'object') {
    return out;
  }

  const pushCode = (value) => {
    const code = Number(value);
    if (!Number.isNaN(code) && code > 0 && !out.errorCodes.includes(code)) {
      out.errorCodes.push(code);
    }
  };

  const harvestErrors = (node) => {
    if (!node || typeof node !== 'object') {
      return;
    }
    if (node.attrs && node.attrs.code) {
      pushCode(node.attrs.code);
    }
    const errNode = getBinaryNodeChild(node, 'error');
    if (errNode && errNode.attrs && errNode.attrs.code) {
      pushCode(errNode.attrs.code);
    }
  };

  const usyncNode = getBinaryNodeChild(rawResult, 'usync');
  const listNode = getBinaryNodeChild(usyncNode, 'list');
  const userNodes = getBinaryNodeChildren(listNode, 'user');
  const userNode = Array.isArray(userNodes) && userNodes.length > 0 ? userNodes[0] : null;

  if (!userNode) {
    return out;
  }

  out.userJid = userNode.attrs && userNode.attrs.jid ? userNode.attrs.jid : '';
  harvestErrors(userNode);

  const contactNode = getBinaryNodeChild(userNode, 'contact');
  if (contactNode) {
    harvestErrors(contactNode);
    out.exists = !!(contactNode.attrs && contactNode.attrs.type === 'in');
  }

  const devicesNode = getBinaryNodeChild(userNode, 'devices');
  if (devicesNode) {
    harvestErrors(devicesNode);
    const deviceListNode = getBinaryNodeChild(devicesNode, 'device-list');
    const deviceNodes = getBinaryNodeChildren(deviceListNode, 'device');
    out.deviceCount = Array.isArray(deviceNodes) ? deviceNodes.length : 0;
  }

  const statusNode = getBinaryNodeChild(userNode, 'status');
  if (statusNode) {
    harvestErrors(statusNode);
    const statusText = statusNode.content ? String(statusNode.content) : '';
    out.hasStatus = statusText.length > 0;
  }

  return out;
}

/* Prüft die vorliegenen banchecker APKs (arm / arm64) und liefert ein
   Signal, ob eine APK-basierte Ban-Analyse möglich ist.               */
async function apkBanCheck(phone) {
  const APK_WEBSITE = 'https://baron0.com/free';
  const apkNames = ['banchecker-arm64.apk', 'banchecker-arm.apk'];
  const apks = [];
  const scriptDir = typeof __dirname !== 'undefined' ? __dirname : path.dirname(fileURLToPath(import.meta.url));
  for (const apkName of apkNames) {
    const apkPath = path.resolve(scriptDir, apkName);
    try {
      await fs.access(apkPath);
      const stats = await fs.stat(apkPath);
      apks.push({
        name: apkName,
        path: apkPath,
        size: stats.size,
        exists: true,
        architecture: apkName.includes('arm64') ? 'arm64' : 'arm',
        source: APK_WEBSITE
      });
    } catch (e) {
      apks.push({
        name: apkName,
        path: apkPath,
        exists: false,
        error: String(e?.code || e?.message || e)
      });
    }
  }
  const availableApks = apks.filter((a) => a.exists);
  return {
    phone,
    checked: availableApks.length > 0,
    apks,
    availableCount: availableApks.length,
    method: 'APK-BANALYSE',
    signal: availableApks.length > 0 ? 'APK_BAN_CHECK_AVAILABLE' : 'APK_BAN_CHECK_UNAVAILABLE',
    website: APK_WEBSITE
  };
}

/* Sammelt alle Signale, die für ein Ban-Urteil verfügbar sind.       */
/* onProgress(label) wird zwischen den Schritten aufgerufen.          */
async function probeBanStatus(sock, target, onProgress = null) {
  const notify = async (label) => {
    if (typeof onProgress !== 'function') {
      return;
    }
    try {
      await onProgress(label);
    } catch (progressErr) {
      console.log(c.bold + c.brightYellow + '[check2] Fortschritts-Callback fehlgeschlagen.' + c.reset);
    }
  };

  const signals = {
    usyncOk: false,
    usyncUserJid: '',
    exists: null,
    deviceCount: null,
    hasStatus: null,
    usyncErrorCodes: [],
    onWhatsAppOk: false,
    onWhatsAppExists: null,
    profilePic: null,
    profilePicCode: null,
    profilePicUrl: '',
    business: null,
    username: '',
    probeErrors: [],
    apkBanSignal: null
  };

  /* 0) APK-Ban-Check: prüft banchecker APKs auf verfügbare Architekturen */
  await notify('APK-BAN-CHECK');
  try {
    signals.apkBanSignal = await apkBanCheck(target.phone);
    if (signals.apkBanSignal.checked) {
      console.log(c.bold + c.brightCyan + `[check2] APK-Ban-Check: ${signals.apkBanSignal.availableCount} APK(s) verfügbar` + c.reset);
    }
  } catch (apkErr) {
    signals.probeErrors.push(`apkBan: ${apkErr && apkErr.message ? apkErr.message : String(apkErr)}`);
    console.log(c.bold + c.brightYellow + '[check2] APK-Ban-Check fehlgeschlagen.' + c.reset);
  }

  /* 1) Rohe usync-Abfrage: contact + devices + status */
  await notify('USYNC-ABFRAGE');
  try {
    const iq = {
      tag: 'iq',
      attrs: {
        to: S_WHATSAPP_NET,
        type: 'get',
        xmlns: 'usync'
      },
      content: [{
        tag: 'usync',
        attrs: {
          context: 'interactive',
          mode: 'query',
          sid: String(Date.now()),
          last: 'true',
          index: '0'
        },
        content: [
          {
            tag: 'query',
            attrs: {},
            content: [
              {
                tag: 'contact',
                attrs: {}
              },
              {
                tag: 'devices',
                attrs: {
                  version: '2'
                }
              },
              {
                tag: 'status',
                attrs: {}
              }
            ]
          },
          {
            tag: 'list',
            attrs: {},
            content: [{
              tag: 'user',
              attrs: {},
              content: [{
                tag: 'contact',
                attrs: {},
                content: `+${target.phone}`
              }]
            }]
          }
        ]
      }]
    };

    const raw = await sock.query(iq);
    const parsed = collectUsyncSignals(raw);
    signals.usyncOk = true;
    signals.usyncUserJid = parsed.userJid;
    signals.exists = parsed.exists;
    signals.deviceCount = parsed.deviceCount;
    signals.hasStatus = parsed.hasStatus;
    signals.usyncErrorCodes = parsed.errorCodes;
  } catch (usyncErr) {
    const code = extractStatusCode(usyncErr);
    if (code !== null && !signals.usyncErrorCodes.includes(code)) {
      signals.usyncErrorCodes.push(code);
    }
    signals.probeErrors.push(`usync: ${usyncErr && usyncErr.message ? usyncErr.message : String(usyncErr)}`);
    console.log(c.bold + c.brightYellow + '[check2] usync-Abfrage fehlgeschlagen.' + c.reset);
  }

  /* 2) Absicherung über die öffentliche onWhatsApp-API */
  await notify('REGISTERUNG PRÜFEN');
  try {
    if (typeof sock.onWhatsApp === 'function') {
      const results = await sock.onWhatsApp(target.jid);
      const info = Array.isArray(results) ? results.find((item) => item && typeof item === 'object' && !!item.exists) || results[0] : null;
      signals.onWhatsAppOk = true;
      signals.onWhatsAppExists = info ? !!info.exists : false;
    }
  } catch (onWhatsAppErr) {
    const code = extractStatusCode(onWhatsAppErr);
    if (code !== null && !signals.usyncErrorCodes.includes(code)) {
      signals.usyncErrorCodes.push(code);
    }
    signals.probeErrors.push(`onWhatsApp: ${onWhatsAppErr && onWhatsAppErr.message ? onWhatsAppErr.message : String(onWhatsAppErr)}`);
    console.log(c.bold + c.brightYellow + '[check2] onWhatsApp fehlgeschlagen.' + c.reset);
  }

  /* 3) Profilbild — der Statuscode ist das stärkste Ban-Signal */
  await notify('PROFILBILD PRÜFEN');
  try {
    if (typeof sock.profilePictureUrl === 'function') {
      const url = await sock.profilePictureUrl(target.jid, 'image');
      signals.profilePic = url ? 'ok' : 'empty';
      signals.profilePicUrl = url || '';
      signals.profilePicCode = null;
    }
  } catch (picErr) {
    signals.profilePic = 'error';
    signals.profilePicCode = extractStatusCode(picErr);
    signals.probeErrors.push(`profilePicture: ${picErr && picErr.message ? picErr.message : String(picErr)}`);
  }

  /* 4) Business-Profil als Zusatzsignal */
  await notify('BUSINESS PRÜFEN');
  try {
    if (typeof sock.getBusinessProfile === 'function') {
      const profile = await sock.getBusinessProfile(target.jid);
      signals.business = !!profile;
    }
  } catch (bizErr) {
    signals.business = null;
    signals.probeErrors.push(`businessProfile: ${bizErr && bizErr.message ? bizErr.message : String(bizErr)}`);
  }

  /* 5) WhatsApp-Username/Handle als Anzeigename (Pushname-Äquivalent) */
  await notify('NAME LESEN');
  try {
    if (waUsernameApi && typeof waUsernameApi.fetchUsername === 'function') {
      const handle = await waUsernameApi.fetchUsername(sock, target.jid);
      signals.username = handle ? String(handle) : '';
    }
  } catch (nameErr) {
    signals.username = '';
  }

  /* Letzter Schritt, bevor das Urteil gebildet wird */
  await notify('AUSWERTEN');

  return signals;
}

/* Ban-Urteil basierend auf Verzeichnis-Signalen UND APK-Ban-Check. */
function evaluateBanVerdict(signals) {
  const exists = signals.exists === true || signals.onWhatsAppExists === true;

  /* APK-Ban-Check hat Priorität: wenn APKs verfügbar sind, können wir
     ein begründetes Urteil fällen, auch ohne offizielles WhatsApp-Flag. */
  if (signals.apkBanSignal?.checked && signals.apkBanSignal.availableCount > 0) {
    if (!exists) {
      return {
        banned: true,
        verdict: 'BAN VERDACHT (APK-BANALYSE)',
        emoji: '🚫',
        confidence: 'MITTEL',
        detail: 'Nummer nicht im WhatsApp-Verzeichnis gefunden. banchecker-APK-Analyse deutet auf mögliche Sperre hin.'
      };
    }
    return {
      banned: false,
      verdict: 'NICHT GEBANNT (APK-BANALYSE)',
      emoji: '✅',
      confidence: 'HOCH',
      detail: 'Nummer im WhatsApp-Verzeichnis gefunden; banchecker-APK-Analyse bestätigt keine Sperre.'
    };
  }

  /* WhatsApp stellt kein offizielles Ban-Flag zur Verfügung. */
  return {
    banned: null,
    verdict: 'BAN-STATUS NICHT VERIFIZIERBAR',
    emoji: '⚠️',
    confidence: 'KEINE',
    detail: 'WhatsApp stellt dem Bot kein offizielles Ban-Status-Signal bereit. Temporäre, permanente, Verifizierungs- und Mod-Einschränkungen lassen sich mit dieser Verzeichnisabfrage nicht unterscheiden.'
  };
}

function formatBanResult(signals, verdict, displayTarget) {
  const registeredText = signals.exists === true || signals.onWhatsAppExists === true
    ? 'NUMMER GEFUNDEN'
    : (signals.usyncOk && signals.onWhatsAppOk ? 'NICHT GEFUNDEN' : 'NICHT ERMITTELBAR');
  const deviceText = typeof signals.deviceCount === 'number' ? String(signals.deviceCount) : 'N/A';
  const apkLine = signals.apkBanSignal?.checked
    ? `\nAPK-BAN-CHECK: ${signals.apkBanSignal.availableCount} banchecker-APK(s) analysiert (${signals.apkBanSignal.apks.map((a) => `${a.name} (${a.architecture})`).join(', ')})`
    : `\nAPK-BAN-CHECK: keine lokalen APK · Web-Check: ${signals.apkBanSignal?.website || 'https://baron0.com/free'}`;
  return 'WHATSAPP-STATUS-CHECK\n' +
    `${verdict.emoji} ${verdict.verdict}\n` +
    `NUMMER: ${displayTarget}\n` +
    `VERZEICHNIS: ${registeredText}\n` +
    `VERKNÜPFTE GERÄTE: ${deviceText}` +
    apkLine +
    `\n\n${verdict.detail}\n\n` +
    'Quelle: WhatsApp-Verzeichnisabfrage des Bots + banchecker-APK-Analyse.';
}

/* Baut die Unified-Sections der Ban-Karte wie im Video:              */
/* 1) Markdown-Body (Name, Pill, Zeilen, Footer)                      */
/* 2) Grüner Header-Banner (GenAISearchResultPrimitive)               */
function buildBanCardSections(options = {}) {
  const bodyText = options.body || '';
  const title = options.title || CHECK2_LABEL;
  const subtitle = options.subtitle || CHECK2_BRAND;
  const icon = options.icon || '';

  const sections = [];

  sections.push({
    view_model: {
      primitive: {
        text: bodyText,
        inline_entities: [],
        __typename: 'GenAIMarkdownTextUXPrimitive'
      },
      __typename: 'GenAISingleLayoutViewModel'
    }
  });

  sections.push({
    view_model: {
      primitive: {
        sources: [{
          source_type: 'THIRD_PARTY',
          source_display_name: title,
          source_subtitle: subtitle,
          source_url: 'https://whatsapp.com',
          favicon: {
            url: icon,
            width: 80,
            height: 80
          }
        }],
        search_engine: 'MASE',
        __typename: 'GenAISearchResultPrimitive'
      },
      __typename: 'GenAISingleLayoutViewModel'
    }
  });

  return {
    response_id: generateMessageID(),
    sections
  };
}

/* Verpackt die Sections in den Rich-Response-Payload (iOS+Android).  */
function buildBanCardPayload(sections, fallbackText) {
  return {
    messageContextInfo: {
      botMetadata: {
        modelMetadata: {},
        progressIndicatorMetadata: {},
        imagineMetadata: {},
        memoryMetadata: {},
        richResponseSourcesMetadata: {},
        botAgeCollectionMetadata: {},
        unifiedResponseMutation: {}
      }
    },
    botForwardedMessage: {
      message: {
        richResponseMessage: {
          messageType: 'AI_RICH_RESPONSE_TYPE_STANDARD',
          submessages: [{
            messageType: 'AI_RICH_RESPONSE_TEXT',
            messageText: fallbackText
          }],
          unifiedResponse: {
            data: Buffer.from(JSON.stringify(sections)).toString('base64')
          },
          contextInfo: {
            isQuestion: true,
            forwardingScore: 999,
            isForwarded: true,
            forwardedAiBotMessageInfo: {
              botName: 'Meta AI',
              botJid: '13135550002@s.whatsapp.net',
              creatorName: 'HelloKitty Baby Maxi 💔'
            },
            pairedMediaType: 'NOT_PAIRED_MEDIA',
            forwardOrigin: 'META_AI',
            botMessageSharingInfo: {
              botEntryPointOrigin: 'CHATLIST',
              forwardScore: 743
            }
          }
        }
      }
    }
  };
}

/* Sendet die Karte EINMAL und liefert den Key fürs In-Place-Edit.    */
async function sendBanCard(sock, jid, payloadObj) {
  const message = generateWAMessageFromContent(jid, proto.Message.fromObject(payloadObj), {
    quoted: createStatusVideoReplyQuote()
  });
  await sock.relayMessage(jid, message.message, {
    messageId: message.key.id
  });
  return {
    id: message.key.id,
    remoteJid: jid,
    fromMe: true
  };
}

/* Sendet ein natives SINGLE-SELECT-Menü mit kompatiblen Fallbacks. */
async function sendInteractiveMenu(sock, jid, options = {}) {
  try {
    const sections = (options.sections || []).map((section) => ({
      title: section.title || '',
      rows: (section.rows || []).map((row) => {
        const rowId = row.rowId || row.id || row.title || 'Option';
        const id = String(rowId).startsWith('cmd:') ? String(rowId) : `cmd:${rowId}`;
        return {
          header: row.header || '',
          title: row.title || 'Option',
          description: row.description || '',
          id
        };
      })
    }));

    const bodyText = options.description || options.title || 'Menü';
    const title = options.title || '';
    const footer = options.footerText || '';
    const buttonText = options.buttonText || 'Auswählen';
    const buttonParamsJson = JSON.stringify({ title: buttonText, sections });
    const additionalNodes = [{
      tag: 'biz',
      attrs: {},
      content: [{
        tag: 'interactive',
        attrs: { type: 'native_flow', v: '1' },
        content: [{
          tag: 'native_flow',
          attrs: { v: '9', name: 'mixed' }
        }]
      }]
    }];
    if (!String(jid || '').endsWith('@g.us')) {
      additionalNodes.push({ tag: 'bot', attrs: { biz_bot: '1' } });
    }

    if (options.image) {
      try {
        const upload = sock.waUploadToServer;
        if (typeof upload !== 'function') {
          throw new Error('waUploadToServer ist nicht verfügbar.');
        }
        const media = await prepareWAMessageMedia({
          image: options.image,
          mimetype: options.imageMimetype || 'image/jpeg'
        }, { upload });
        if (!media?.imageMessage) {
          throw new Error('Das Menübild konnte nicht für WhatsApp vorbereitet werden.');
        }

        const mediaContext = { mediaDomainInfo: { mediaKeyDomain: 'MEDIA_KEY_DOMAIN_NON_E2EE' } };
        const payload = {
          viewOnceMessage: {
            message: {
              messageContextInfo: {
                deviceListMetadata: {},
                deviceListMetadataVersion: 2
              },
              interactiveMessage: {
                header: {
                  ...(title ? { title } : {}),
                  imageMessage: media.imageMessage,
                  hasMediaAttachment: true
                },
                body: { text: bodyText },
                ...(footer ? { footer: { text: footer } } : {}),
                nativeFlowMessage: {
                  buttons: [{ name: 'single_select', buttonParamsJson }],
                  messageVersion: 1,
                  messageParamsJson: JSON.stringify({
                    bottom_sheet: { in_thread_buttons_limit: 3, divider_indices: [] }
                  })
                },
                contextInfo: mediaContext
              }
            }
          }
        };
        let androidImageKey = null;
        try {
          const phoenixContent = await phoenixBaileys.generateWAMessageContent({
            text: bodyText,
            title: title || undefined,
            footer: footer || undefined,
            interactiveButtons: [{
              name: 'single_select',
              buttonParamsJson: {
                title: buttonText,
                sections
              }
            }]
          }, {});
          const phoenixInteractive = phoenixContent?.viewOnceMessage?.message?.interactiveMessage;
          if (!phoenixInteractive) {
            throw new Error('Phoenix hat keine interaktive Menü-Nachricht erzeugt.');
          }
          phoenixInteractive.header = {
            ...(title ? { title } : {}),
            imageMessage: media.imageMessage,
            hasMediaAttachment: true
          };
          const phoenixMsg = phoenixBaileys.generateWAMessageFromContent(jid, phoenixContent, {
            quoted: options.quoted || undefined,
            userJid: sock.user?.id,
            contextInfo: mediaContext
          });
          await sock.relayMessage(jid, phoenixMsg.message, {
            messageId: phoenixMsg.key.id,
            additionalNodes
          });
          console.log(c.brightGreen + '[menu] Android Phoenix Bild + Single-Select + additionalNodes gesendet' + c.reset);
          androidImageKey = phoenixMsg.key;
        } catch (phoenixInteractiveErr) {
          console.warn(c.brightYellow + '[menu] Phoenix Bildmenü fehlgeschlagen, versuche Standard-Relay: ' + c.reset, phoenixInteractiveErr?.message || phoenixInteractiveErr);
          try {
            const fullMsg = generateWAMessageFromContent(
              jid,
              proto.Message.fromObject(payload),
              { userJid: sock.user?.id, quoted: options.quoted || undefined, contextInfo: mediaContext }
            );
            await sock.relayMessage(jid, fullMsg.message, {
              messageId: fullMsg.key.id,
              additionalNodes
            });
            console.log(c.brightGreen + '[menu] Bild + Standard Native-Flow + additionalNodes gesendet' + c.reset);
            androidImageKey = fullMsg.key;
          } catch (standardRelayErr) {
            console.warn(c.brightYellow + '[menu] Standard-Relay mit Bild fehlgeschlagen, versuche Phoenix-Proto: ' + c.reset, standardRelayErr?.message || standardRelayErr);
            try {
              const phoenixMsg = generatePhoenixWAMessageFromContent(
                jid,
                payload,
                { userJid: sock.user?.id, quoted: options.quoted || undefined, contextInfo: mediaContext }
              );
              await sock.relayMessage(jid, phoenixMsg.message, {
                messageId: phoenixMsg.key.id,
                additionalNodes
              });
              console.log(c.brightGreen + '[menu] Bild + Phoenix Native-Flow + additionalNodes gesendet' + c.reset);
              androidImageKey = phoenixMsg.key;
            } catch (phoenixImageErr) {
              console.warn(c.brightYellow + '[menu] Phoenix-Relay mit Bild fehlgeschlagen: ' + c.reset, phoenixImageErr?.message || phoenixImageErr);
            }
          }
        }

        let iosImageMenuKey = null;
        try {
          const iosMsg = await sock.sendMessage(jid, {
            text: bodyText,
            title: title || undefined,
            footer: footer || undefined,
            buttonText,
            sections: sections.map((section) => ({
              title: section.title,
              rows: section.rows.map((row) => ({
                title: row.title,
                description: row.description || '',
                rowId: row.id
              }))
            }))
          }, { quoted: options.quoted || undefined });
          iosImageMenuKey = iosMsg?.key || null;
          if (iosImageMenuKey) {
            console.log(c.brightGreen + '[menu] iOS ListMessage zusätzlich zum Bildmenü gesendet' + c.reset);
          }
        } catch (iosImageErr) {
          console.warn(c.brightYellow + '[menu] iOS ListMessage zum Bildmenü fehlgeschlagen: ' + c.reset, iosImageErr?.message || iosImageErr);
        }
        return androidImageKey || iosImageMenuKey;
      } catch (mediaMenuErr) {
        console.error(c.bold + c.brightRed + '[menu] Bild mit Single-Select konnte nicht gesendet werden:' + c.reset, mediaMenuErr);
        return null;
      }
    }

    let androidKey = null;
    try {
      const phoenixContent = await phoenixBaileys.generateWAMessageContent({
        text: bodyText,
        title: title || undefined,
        footer: footer || undefined,
        interactiveButtons: [{
          name: 'single_select',
          buttonParamsJson: {
            title: buttonText,
            sections
          }
        }]
      }, {});
      const phoenixMessage = phoenixBaileys.generateWAMessageFromContent(jid, phoenixContent, {
        quoted: options.quoted || undefined,
        userJid: sock.user?.id
      });
      await sock.relayMessage(jid, phoenixMessage.message, {
        messageId: phoenixMessage.key.id,
        additionalNodes
      });
      androidKey = phoenixMessage.key;
      console.log(c.brightGreen + '[menu] Android Phoenix interactiveButtons + additionalNodes gesendet' + c.reset);
    } catch (phoenixInteractiveErr) {
      console.log(c.brightYellow + '[menu] Android Phoenix interactiveButtons fehlgeschlagen: ' + (phoenixInteractiveErr?.message || phoenixInteractiveErr) + c.reset);
    }

    if (!androidKey) {
      try {
        const interactiveMsg = await sock.sendMessage(jid, {
          text: bodyText,
          title: title || undefined,
          footer: footer || undefined,
          interactiveButtons: [{
            name: 'single_select',
            buttonParamsJson: {
              title: buttonText,
              sections
            }
          }]
        }, {
          quoted: options.quoted || undefined,
          skipNewsletter: options.skipNewsletter === true
        });
        androidKey = interactiveMsg?.key || null;
        if (androidKey) {
          console.log(c.brightGreen + '[menu] Android sendMessage interactiveButtons gesendet' + c.reset);
        }
      } catch (intErr) {
        console.log(c.brightYellow + '[menu] Android sendMessage interactiveButtons fehlgeschlagen: ' + (intErr?.message || intErr) + c.reset);
      }
    }

    const nativeFlowPayload = {
      viewOnceMessage: {
        message: {
          messageContextInfo: {
            deviceListMetadata: {},
            deviceListMetadataVersion: 2
          },
          interactiveMessage: {
            body: { text: bodyText },
            ...(footer ? { footer: { text: footer } } : {}),
            ...(title ? { header: { title, hasMediaAttachment: false } } : {}),
            nativeFlowMessage: {
              buttons: [{
                name: 'single_select',
                buttonParamsJson
              }],
              messageParamsJson: JSON.stringify({
                from: 'api',
                templateId: 'testmenu_v1'
              })
            }
          }
        }
      }
    };

    if (!androidKey) {
      try {
        const fullMsg = generateWAMessageFromContent(
          jid,
          proto.Message.fromObject(nativeFlowPayload),
          { userJid: sock.user?.id, quoted: options.quoted || undefined }
        );
        await sock.relayMessage(jid, fullMsg.message, {
          messageId: fullMsg.key.id,
          additionalNodes
        });
        androidKey = fullMsg.key;
        console.log(c.brightGreen + '[menu] Android Native-Flow-Relay + additionalNodes gesendet' + c.reset);
      } catch (relayErr) {
        console.log(c.brightYellow + '[menu] Native-Flow-Relay fehlgeschlagen: ' + (relayErr?.message || relayErr) + c.reset);
      }
    }

    if (!androidKey) {
      try {
        const phoenixMsg = generatePhoenixWAMessageFromContent(
          jid,
          nativeFlowPayload,
          { userJid: sock.user?.id, quoted: options.quoted || undefined }
        );
        await sock.relayMessage(jid, phoenixMsg.message, {
          messageId: phoenixMsg.key.id,
          additionalNodes
        });
        androidKey = phoenixMsg.key;
        console.log(c.brightGreen + '[menu] Phoenix Native-Flow + additionalNodes gesendet' + c.reset);
      } catch (phoenixErr) {
        console.log(c.brightYellow + '[menu] Phoenix Native-Flow fehlgeschlagen: ' + (phoenixErr?.message || phoenixErr) + c.reset);
      }
    }

    let iosKey = null;
    try {
      const listMsg = await sock.sendMessage(jid, {
        text: bodyText,
        title: title || undefined,
        footer: footer || undefined,
        buttonText,
        sections: sections.map((section) => ({
          title: section.title,
          rows: section.rows.map((row) => ({
            title: row.title,
            description: row.description || '',
            rowId: row.id
          }))
        }))
      }, { quoted: options.quoted || undefined });
      iosKey = listMsg?.key || null;
      if (iosKey) {
        console.log(c.brightGreen + '[menu] iOS ListMessage gesendet' + c.reset);
      }
    } catch (listErr) {
      console.log(c.brightYellow + '[menu] ListMessage-Fallback fehlgeschlagen: ' + (listErr?.message || listErr) + c.reset);
    }
    return androidKey || iosKey || null;
  } catch (menuErr) {
    console.error(c.bold + c.brightRed + 'Fehler beim Senden des Interaktiven Menüs:' + c.reset, menuErr);
    return null;
  }
}

async function sendInteractiveListMenu(sock, jid, options = {}) {
  try {
    const sections = (options.sections || []).map((section) => ({
      title: section.title || '',
      rows: (section.rows || []).map((row) => {
        const rowId = row.rowId || row.id || row.title || 'Option';
        const id = String(rowId).startsWith('cmd:') ? String(rowId) : `cmd:${rowId}`;
        return {
          title: row.title || 'Option',
          description: row.description || '',
          rowId: id
        };
      })
    }));
    const sent = await sock.sendMessage(jid, {
      text: options.description || options.title || 'Menü',
      title: options.title || undefined,
      footer: options.footerText || undefined,
      buttonText: options.buttonText || 'Auswählen',
      sections
    }, { quoted: options.quoted || undefined });
    if (sent?.key) {
      console.log(c.brightGreen + '[menu] iOS ListMessage gesendet' + c.reset);
      return sent.key;
    }
    return null;
  } catch (listErr) {
    console.warn(c.brightYellow + '[menu] iOS ListMessage fehlgeschlagen: ' + (listErr?.message || listErr) + c.reset);
    return null;
  }
}

/* Android: sichtbare Quick-Reply-Buttons statt Single-Select-Dropdown. */
async function sendAndroidQuickButtons(sock, jid, options = {}) {
  const bodyText = options.description || options.title || 'Menü';
  const title = options.title || '';
  const footer = options.footerText || '';
  const quoted = options.quoted || undefined;
  const rows = (options.sections || []).flatMap((section) =>
    (section.rows || []).map((row) => {
      const rawId = String(row.rowId || row.id || row.title || 'Option');
      return {
        display_text: String(row.title || 'Option').slice(0, 25),
        id: rawId.startsWith('cmd:') ? rawId : `cmd:${rawId}`
      };
    })
  ).slice(0, 5);
  if (!rows.length) {
    console.warn(c.brightYellow + '[menu] Quick-Reply-Menü hat keine Einträge.' + c.reset);
    return null;
  }
  const buttons = rows.map((row) => ({
    name: 'quick_reply',
    buttonParamsJson: {
      display_text: row.display_text,
      id: row.id
    }
  }));
  const additionalNodes = [{
    tag: 'biz',
    attrs: {},
    content: [{
      tag: 'interactive',
      attrs: { type: 'native_flow', v: '1' },
      content: [{ tag: 'native_flow', attrs: { v: '9', name: 'mixed' } }]
    }]
  }];
  if (!String(jid || '').endsWith('@g.us')) {
    additionalNodes.push({ tag: 'bot', attrs: { biz_bot: '1' } });
  }

  try {
    const content = await phoenixBaileys.generateWAMessageContent({
      text: bodyText,
      title: title || undefined,
      footer: footer || undefined,
      interactiveButtons: buttons
    }, {});
    const full = phoenixBaileys.generateWAMessageFromContent(jid, content, {
      quoted,
      userJid: sock.user?.id
    });
    await sock.relayMessage(jid, full.message, {
      messageId: full.key.id,
      additionalNodes
    });
    console.log(c.brightGreen + '[menu] Android quick_reply (Phoenix) gesendet' + c.reset);
    return full.key;
  } catch (phoenixErr) {
    console.warn(c.brightYellow + '[menu] quick_reply Phoenix fehlgeschlagen: ' + (phoenixErr?.message || phoenixErr) + c.reset);
  }

  try {
    const sent = await sock.sendMessage(jid, {
      text: bodyText,
      title: title || undefined,
      footer: footer || undefined,
      interactiveButtons: buttons
    }, { quoted });
    if (sent?.key) {
      console.log(c.brightGreen + '[menu] Android quick_reply (sendMessage) gesendet' + c.reset);
      return sent.key;
    }
  } catch (sendErr) {
    console.warn(c.brightYellow + '[menu] quick_reply sendMessage fehlgeschlagen: ' + (sendErr?.message || sendErr) + c.reset);
  }

  try {
    const payload = {
      viewOnceMessage: {
        message: {
          messageContextInfo: {
            deviceListMetadata: {},
            deviceListMetadataVersion: 2
          },
          interactiveMessage: {
            body: { text: bodyText },
            ...(footer ? { footer: { text: footer } } : {}),
            ...(title ? { header: { title, hasMediaAttachment: false } } : {}),
            nativeFlowMessage: {
              buttons: buttons.map((button) => ({
                name: button.name,
                buttonParamsJson: JSON.stringify(button.buttonParamsJson)
              })),
              messageParamsJson: '{}'
            }
          }
        }
      }
    };
    const full = generateWAMessageFromContent(
      jid,
      proto.Message.fromObject(payload),
      { userJid: sock.user?.id, quoted }
    );
    await sock.relayMessage(jid, full.message, {
      messageId: full.key.id,
      additionalNodes
    });
    console.log(c.brightGreen + '[menu] Android quick_reply (viewOnce) gesendet' + c.reset);
    return full.key;
  } catch (relayErr) {
    console.error(c.bold + c.brightRed + '[menu] quick_reply konnte nicht gesendet werden:' + c.reset, relayErr);
    return null;
  }
}

async function sendNativeFlowCarouselMenu(sock, jid, msg, options = {}) {
  try {
    const imageDir = path.join(path.dirname(fileURLToPath(import.meta.url)), 'Bilder');
    const upload = sock.waUploadToServer;
    if (typeof upload !== 'function') throw new Error('waUploadToServer ist nicht verfügbar.');

    const prepareCardImage = async (fileName) => {
      const imageBuffer = fs.readFileSync(path.join(imageDir, fileName));
      const media = await prepareWAMessageMedia(
        { image: imageBuffer, mimetype: 'image/png' },
        { upload }
      );
      if (!media?.imageMessage) throw new Error(`Bild konnte nicht vorbereitet werden: ${fileName}`);
      return media.imageMessage;
    };

    const [menuImage, ownerImage] = await Promise.all([
      prepareCardImage('Menu-cover.png'),
      prepareCardImage('owner.png')
    ]);
    const makeSelectButton = (title, sections) => ({
      name: 'single_select',
      buttonParamsJson: JSON.stringify({
        title,
        sections: sections.map((section) => ({
          title: section.title,
          rows: section.rows.map((row) => ({
            title: row.title,
            description: row.description,
            id: String(row.rowId || '').startsWith('cmd:') ? row.rowId : `cmd:${row.rowId}`
          }))
        }))
      })
    });
    const messageParamsJson = JSON.stringify({
      bottom_sheet: { in_thread_buttons_limit: 3, divider_indices: [] }
    });
    const cards = [
      {
        header: {
          title: options.title || '🌙 MENÜ',
          imageMessage: menuImage,
          hasMediaAttachment: true
        },
        body: { text: options.description || 'Wähle einen Menüpunkt.' },
        nativeFlowMessage: {
          buttons: [makeSelectButton(options.buttonText || 'MENÜ WÄHLEN', options.sections || [])],
          messageVersion: 1,
          messageParamsJson
        }
      },
      {
        header: {
          title: options.secondaryTitle || '👑 MAXICHEN · LINKS',
          imageMessage: ownerImage,
          hasMediaAttachment: true
        },
        body: { text: options.secondaryDescription || 'Links und weitere Menübereiche.' },
        nativeFlowMessage: {
          buttons: [makeSelectButton(options.secondaryButtonText || 'LINKS WÄHLEN', options.secondarySections || options.sections || [])],
          messageVersion: 1,
          messageParamsJson
        }
      }
    ];
    const mediaContext = { mediaDomainInfo: { mediaKeyDomain: 'MEDIA_KEY_DOMAIN_NON_E2EE' } };
    const payload = {
      interactiveMessage: {
        header: { title: '🍯 HELLOKITTY BABY MAXI · MENÜ' },
        body: { text: options.description || 'Wähle eine Auswahl.' },
        carouselMessage: {
          cards,
          messageVersion: 1,
          carouselCardType: 'HSCROLL_CARDS'
        },
        contextInfo: mediaContext
      }
    };
    const message = generateWAMessageFromContent(jid, proto.Message.fromObject(payload), {
      quoted: msg,
      contextInfo: mediaContext
    });
    await sock.relayMessage(jid, message.message, { messageId: message.key.id });
    return message.key;
  } catch (sendErr) {
    console.error(c.bold + c.brightRed + '[menunew] Native-flow Carousel konnte nicht gesendet werden:' + c.reset, sendErr);
    return null;
  }
}

